// This code snippet addresses the issue of hypocrisy in labeling.
// It aims to identify and highlight instances where labels may not align with actions or values.

function checkLabelHypocrisy(labels, actions) {
    let hypocriticalLabels = [];

    labels.forEach((label, index) => {
        if (!actions.includes(label)) {
            hypocriticalLabels.push(label);
        }
    });

    return hypocriticalLabels;
}

// Example usage:
let labels = ['eco-friendly', 'fair-trade', 'organic'];
let actions = ['uses plastic', 'exploits labor', 'uses pesticides'];

let result = checkLabelHypocrisy(labels, actions);
console.log('Hypocritical Labels:', result);

