// This code snippet highlights the importance of leadership in an organization.
// It emphasizes how effective leadership can drive success and foster a positive work environment.

function assessLeadershipImpact(teamPerformance, employeeSatisfaction) {
    if (teamPerformance > 8 && employeeSatisfaction > 8) {
        return Leadership is highly effective.;
    } else if (teamPerformance > 5 && employeeSatisfaction > 5) {
        return Leadership is moderately effective.;
    } else {
        return Leadership needs improvement.;
    }
}

// Example usage:
let teamPerformance = 9; // Scale of 1-10
let employeeSatisfaction = 9; // Scale of 1-10

console.log(assessLeadershipImpact(teamPerformance, employeeSatisfaction));
// Output: Leadership is highly effective.

